static int ip(int a, int b, int c, int d) { return a << 24 | b << 16 | c << 8 | d; }

static boolean inRange(int addr, int network, int prefix) {
    int mask = -1 << (32 - prefix);
    return (addr & mask) == (network & mask);
}

public static void main(String[] args) {
    int subnet = ip(10, 0, 16, 0);
    System.out.println(inRange(ip(10, 0, 31, 200), subnet, 20));
    System.out.println(inRange(ip(10, 0, 32, 9), subnet, 20));
    System.out.println(inRange(ip(10, 0, 15, 255), subnet, 20));
}
